        var update = NewUser("ada.lovelace@example.com", new Preferences { Language = "fr", TimeZone = "Europe/Paris" });
        Assert.AreEqual(HttpStatusCode.OK, (await Client.PutAsJsonAsync($"/users/{created.Id}", update)).StatusCode);

